using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.UI;
[InitializeOnLoad]public static class DayNightSwitchTest{static CityDayNightController c;static int stage;static double start;static float duration;static bool original;static string log;static DayNightSwitchTest(){EditorApplication.update+=Tick;}static void Tick(){if(EditorApplication.isCompiling)return;try{if(stage==0){if(!File.Exists("DayNightSwitchTest.request"))return;File.Delete("DayNightSwitchTest.request");c=UnityEngine.Object.FindObjectOfType<CityDayNightController>();original=c.IsNight;duration=c.transitionSeconds;c.transitionSeconds=1;c.Apply(false);log="Day global="+Shader.GetGlobalFloat("_GangstarNight")+" sun="+c.sun.intensity+"\n";foreach(var b in Resources.FindObjectsOfTypeAll<Button>().Where(b=>b.gameObject.scene.IsValid()))for(int i=0;i<b.onClick.GetPersistentEventCount();i++)log+=b.name+" => "+b.onClick.GetPersistentMethodName(i)+" target="+b.onClick.GetPersistentTarget(i)+"\n";c.TransitionTo(true);stage=1;start=EditorApplication.timeSinceStartup;return;}if(EditorApplication.timeSinceStartup-start<1.5)return;if(stage==1){log+="Night after actual editor ticks: global="+Shader.GetGlobalFloat("_GangstarNight")+" blend="+c.NightBlend+" transitioning="+c.IsTransitioning+" sun="+c.sun.intensity+"\n";c.TransitionTo(false);stage=2;start=EditorApplication.timeSinceStartup;return;}log+="Day after actual editor ticks: global="+Shader.GetGlobalFloat("_GangstarNight")+" blend="+c.NightBlend+" transitioning="+c.IsTransitioning+" sun="+c.sun.intensity;c.transitionSeconds=duration;c.Apply(original);stage=0;File.WriteAllText("FinalEnvironmentRoadReview/DayNightSwitchTest.txt",log);}catch(Exception e){stage=0;File.WriteAllText("FinalEnvironmentRoadReview/DayNightSwitchTest.txt",e.ToString());}}}
